#!/usr/bin/env node
/**
 * PurgeCSS Configuration for ULS
 * 
 * Scans HTML files (and optionally JS/JSX files) for used class names
 * and generates PurgeCSS configuration to remove unused CSS.
 * 
 * Supports both ULS repository and user projects.
 */

import { readFileSync, existsSync } from 'fs'
import { resolve } from 'path'
import { glob } from 'glob'
import { createRequire } from 'module'

/**
 * Detect if running in ULS repo or user project
 */
function detectContext() {
  const projectRoot = process.cwd()
  
  // Priority 1: Check for user-specified content paths via environment variables
  // This allows users to override auto-detection
  const envSourceDirs = process.env.ULS_PURGE_SOURCE_DIRS
  const envHtmlFiles = process.env.ULS_PURGE_HTML_FILES
  
  if (envSourceDirs || envHtmlFiles) {
    return {
      isUlsRepo: false,
      projectRoot,
      sourceDirs: envSourceDirs ? envSourceDirs.split(',').map(s => s.trim()) : ['src'],
      htmlFiles: envHtmlFiles ? envHtmlFiles.split(',').map(s => s.trim()) : ['**/*.html', 'index.html'],
      safelist: []
    }
  }
  
  // Priority 2: Check for uls.config.cjs (user project config)
  // This takes precedence even if we're in ULS repo
  const configPath = resolve(projectRoot, 'uls.config.cjs')
  if (existsSync(configPath)) {
    try {
      const require = createRequire(import.meta.url)
      const userConfig = require(configPath)
      
      // If config has purge settings, use them (user project)
      if (userConfig.purge) {
        return {
          isUlsRepo: false,
          projectRoot,
          // Only use sourceDirs if explicitly set (don't default to ['src'])
          sourceDirs: userConfig.purge.sourceDirs !== undefined ? userConfig.purge.sourceDirs : undefined,
          htmlFiles: userConfig.purge.htmlFiles || ['**/*.html', 'index.html'],
          safelist: userConfig.purge.safelist || []
        }
      }
    } catch (e) {
      console.warn('⚠️  Could not load uls.config.cjs, using defaults')
    }
  }
  
  // Priority 3: Check if we're in ULS repo AND user wants to scan demo files
  // Only scan ULS demo files if explicitly requested via environment variable
  const scanUlsDemo = process.env.ULS_SCAN_DEMO === 'true'
  const packageJsonPath = resolve(projectRoot, 'package.json')
  if (scanUlsDemo && existsSync(packageJsonPath)) {
    try {
      const pkg = JSON.parse(readFileSync(packageJsonPath, 'utf8'))
      // ULS repo has name: "uls-v2"
      if (pkg.name === 'uls-v2') {
        // Only use ULS repo paths if explicitly requested
        return {
          isUlsRepo: true,
          projectRoot,
          sourceDirs: ['src', 'src/libs/uls-primereact/src', 'src/uls-components/src'],
          htmlFiles: ['src/libs/uls-primereact/index.html', '**/*.html']
        }
      }
    } catch (e) {
      // Continue to user project detection
    }
  }
  
  // Priority 4: Default to user project behavior
  // Only scan HTML files by default - don't scan JS files unless explicitly requested
  return {
    isUlsRepo: false,
    projectRoot,
    sourceDirs: undefined, // Don't scan JS files by default - user must opt-in
    htmlFiles: ['**/*.html', 'index.html'],
    safelist: []
  }
}

/**
 * Scan HTML files for class names
 */
function scanHtmlFiles(htmlPatterns, projectRoot, isUlsRepo = false) {
  const classNames = new Set()
  const foundFiles = []
  
  // Ignore patterns for user projects (exclude demo apps)
  const ignorePatterns = ['node_modules/**', 'dist/**']
  if (!isUlsRepo) {
    // In user projects, exclude ULS demo directories
    ignorePatterns.push('**/demo/**', '**/uls-primereact/**', '**/uls-components/**')
  }
  
  for (const pattern of htmlPatterns) {
    try {
      const files = glob.sync(pattern, { 
        cwd: projectRoot, 
        absolute: false,
        ignore: ignorePatterns
      })
      
      for (const file of files) {
        const fullPath = resolve(projectRoot, file)
        if (!existsSync(fullPath)) continue
        
        try {
          const content = readFileSync(fullPath, 'utf8')
          foundFiles.push(file)
          
          // Extract class names from class="..." attributes
          const classRegex = /\bclass\s*=\s*["']([^"']+)["']/gi
          let match
          while ((match = classRegex.exec(content)) !== null) {
            const classes = match[1].split(/\s+/).filter(Boolean)
            classes.forEach(cls => classNames.add(cls))
          }
          
          // Also check for className in script tags (for JSX-like syntax)
          const classNameRegex = /\bclassName\s*=\s*["']([^"']+)["']/gi
          while ((match = classNameRegex.exec(content)) !== null) {
            const classes = match[1].split(/\s+/).filter(Boolean)
            classes.forEach(cls => classNames.add(cls))
          }
        } catch (err) {
          // Skip files that can't be read
        }
      }
    } catch (err) {
      // Pattern might not match any files, continue
    }
  }
  
  return { classNames: Array.from(classNames), foundFiles }
}

/**
 * Scan JS/JSX/TS files for class names (optional, for React/Vue projects)
 */
function scanSourceFiles(sourceDirs, projectRoot, isUlsRepo = false) {
  const classNames = new Set()
  const extensions = ['js', 'jsx', 'ts', 'tsx']
  
  // Ignore patterns for user projects (exclude demo apps)
  const ignorePatterns = []
  if (!isUlsRepo) {
    // In user projects, exclude ULS demo directories
    ignorePatterns.push('**/demo/**', '**/uls-primereact/**', '**/uls-components/**')
  }
  
  for (const dir of sourceDirs) {
    const fullPath = resolve(projectRoot, dir)
    if (!existsSync(fullPath)) {
      continue
    }
    
    const pattern = `${dir}/**/*.{${extensions.join(',')}}`
    try {
      const files = glob.sync(pattern, { 
        cwd: projectRoot, 
        absolute: false,
        ignore: ignorePatterns.length > 0 ? ignorePatterns : undefined
      })
      
      for (const file of files) {
        try {
          const content = readFileSync(resolve(projectRoot, file), 'utf8')
          
          // Extract class names from className="..." or class="..."
          const classRegex = /\bclass(Name)?\s*=\s*["'`]([^"'`]+)["'`]/g
          let match
          while ((match = classRegex.exec(content)) !== null) {
            const classes = match[2].split(/\s+/).filter(Boolean)
            classes.forEach(cls => classNames.add(cls))
          }
          
          // Extract from template literals: className={`uls-button ${variant}`}
          const templateLiteralRegex = /\bclass(Name)?\s*=\s*\{`([^`]+)`\}/g
          while ((match = templateLiteralRegex.exec(content)) !== null) {
            const templateContent = match[2]
            // Extract string parts and variable interpolations
            const parts = templateContent.split(/\$\{[^}]+\}/)
            parts.forEach(part => {
              const classes = part.trim().split(/\s+/).filter(Boolean)
              classes.forEach(cls => classNames.add(cls))
            })
          }
          
          // Extract from classNames() or clsx() calls
          const classNamesRegex = /\b(classNames?|clsx)\s*\(([^)]+)\)/g
          while ((match = classNamesRegex.exec(content)) !== null) {
            const inside = match[2]
            // Extract string literals
            const stringRegex = /["'`]([^"'`]+)["'`]/g
            let strMatch
            while ((strMatch = stringRegex.exec(inside)) !== null) {
              const classes = strMatch[1].split(/\s+/).filter(Boolean)
              classes.forEach(cls => classNames.add(cls))
            }
            // Also extract object keys (for conditional classes like { 'uls-button': true })
            const objectKeyRegex = /['"]([^'"]+)['"]\s*:/g
            while ((strMatch = objectKeyRegex.exec(inside)) !== null) {
              classNames.add(strMatch[1])
            }
          }
          
          // Extract from array.join() patterns: ['uls-button', variant].join(' ')
          const arrayJoinRegex = /\[([^\]]+)\]\s*\.\s*join\s*\(/g
          while ((match = arrayJoinRegex.exec(content)) !== null) {
            const arrayContent = match[1]
            const stringRegex = /["'`]([^"'`]+)["'`]/g
            let strMatch
            while ((strMatch = stringRegex.exec(arrayContent)) !== null) {
              classNames.add(strMatch[1])
            }
          }
        } catch (err) {
          // Skip files that can't be read
        }
      }
    } catch (err) {
      // Pattern might not match, continue
    }
  }
  
  return Array.from(classNames)
}

/**
 * Get PurgeCSS configuration
 */
export function getPurgeCSSConfig(options = {}) {
  const context = detectContext()
  const { scanJsFiles = false, sourceDirs, htmlFiles } = options
  
  // Override with options if provided (highest priority)
  if (sourceDirs || htmlFiles) {
    context.sourceDirs = sourceDirs || context.sourceDirs
    context.htmlFiles = htmlFiles || context.htmlFiles
    context.isUlsRepo = false // If explicitly provided, treat as user project
  }
  
  console.log(`📦 Context: ${context.isUlsRepo ? 'ULS Repository' : 'User Project'}`)
  
  // Scan HTML files (exclude demo apps in user projects)
  const htmlResult = scanHtmlFiles(context.htmlFiles, context.projectRoot, context.isUlsRepo)
  console.log(`📄 Found ${htmlResult.foundFiles.length} HTML file(s)`)
  if (htmlResult.foundFiles.length > 0 && htmlResult.foundFiles.length <= 5) {
    console.log(`   ${htmlResult.foundFiles.join(', ')}`)
  } else if (htmlResult.foundFiles.length > 5) {
    console.log(`   ${htmlResult.foundFiles.slice(0, 5).join(', ')} ... and ${htmlResult.foundFiles.length - 5} more`)
  }
  
  // Scan JS files only if sourceDirs is explicitly provided
  // Don't scan by default - user must opt-in by setting sourceDirs in config
  let jsClassNames = []
  if (context.sourceDirs && context.sourceDirs.length > 0) {
    jsClassNames = scanSourceFiles(context.sourceDirs, context.projectRoot, context.isUlsRepo)
    if (jsClassNames.length > 0) {
      console.log(`📂 Scanned ${context.sourceDirs.join(', ')} for JS/JSX classes`)
    }
  }
  
  // Combine all class names
  const allClassNames = new Set([...htmlResult.classNames, ...jsClassNames])
  console.log(`✅ Found ${allClassNames.size} unique class names`)
  
  // Build content paths for PurgeCSS
  // Always include JS/JSX/TS files for better class detection
  // Also include Handlebars (.hbs) files
  const contentPaths = [
    ...context.htmlFiles,
    ...(context.sourceDirs 
      ? context.sourceDirs.map(dir => `${dir}/**/*.{js,jsx,ts,tsx}`)
      : []),
    // Add Handlebars files support
    '**/*.hbs',
    ...(context.sourceDirs 
      ? context.sourceDirs.map(dir => `${dir}/**/*.hbs`)
      : [])
  ]
  
  // Minimal safelist: Only keep classes that are dynamically toggled and can't be detected
  // All other classes (including utilities) will be purged if not found in content files
  // This provides true Tailwind-like behavior: only what you use gets included
  const defaultSafelist = [
    // ==========================================================================
    // THEME & MODE CLASSES (Dynamically toggled - must keep)
    // ==========================================================================
    // Theme classes are added/removed via JavaScript, so they might not be detected
    // in static content scanning. Keep all theme classes.
    /^uls-.*-theme$/,
    /^uls-.*-mode$/,
    
    // ==========================================================================
    // PRINT STYLES (Might be added dynamically)
    // ==========================================================================
    /print/,
    
    // ==========================================================================
    // CSS VARIABLES & KEYFRAMES (Handled separately by PurgeCSS)
    // ==========================================================================
    // These are preserved via the variables: true and keyframes: true options
  ]
  
  // Merge user safelist with defaults
  const fullSafelist = [
    ...defaultSafelist,
    ...(context.safelist || []),
    ...(options.safelist || [])
  ]
  
  return {
    content: contentPaths,
    safelist: fullSafelist,
    defaultExtractor: (content) => {
      // Comprehensive extractor for class name detection
      // Extracts classes from all common patterns in HTML/JSX/JS files
      const classNames = new Set()
      
      // 1. Standard class="..." and className="..." attributes
      const classAttrRegex = /\bclass(Name)?\s*=\s*["'`]([^"'`]+)["'`]/g
      let match
      while ((match = classAttrRegex.exec(content)) !== null) {
        const classes = match[2].split(/\s+/).filter(Boolean)
        classes.forEach(cls => classNames.add(cls))
      }
      
      // 2. Template literals: className={`uls-button ${variant}`}
      const templateLiteralRegex = /\bclass(Name)?\s*=\s*\{`([^`]+)`\}/g
      while ((match = templateLiteralRegex.exec(content)) !== null) {
        const templateContent = match[2]
        // Extract string parts (ignore ${} interpolations as they're variables)
        const parts = templateContent.split(/\$\{[^}]+\}/)
        parts.forEach(part => {
          const classes = part.trim().split(/\s+/).filter(Boolean)
          classes.forEach(cls => classNames.add(cls))
        })
      }
      
      // 3. classNames() or clsx() function calls
      const classNamesRegex = /\b(classNames?|clsx)\s*\(([^)]+)\)/g
      while ((match = classNamesRegex.exec(content)) !== null) {
        const inside = match[2]
        // Extract string literals
        const stringRegex = /["'`]([^"'`]+)["'`]/g
        let strMatch
        while ((strMatch = stringRegex.exec(inside)) !== null) {
          const classes = strMatch[1].split(/\s+/).filter(Boolean)
          classes.forEach(cls => classNames.add(cls))
        }
        // Extract object keys (for conditional classes like { 'uls-button': true })
        const objectKeyRegex = /['"]([^'"]+)['"]\s*:/g
        while ((strMatch = objectKeyRegex.exec(inside)) !== null) {
          classNames.add(strMatch[1])
        }
      }
      
      // 4. Array.join() patterns: ['uls-button', variant].join(' ')
      const arrayJoinRegex = /\[([^\]]+)\]\s*\.\s*join\s*\(/g
      while ((match = arrayJoinRegex.exec(content)) !== null) {
        const arrayContent = match[1]
        const stringRegex = /["'`]([^"'`]+)["'`]/g
        let strMatch
        while ((strMatch = stringRegex.exec(arrayContent)) !== null) {
          classNames.add(strMatch[1])
        }
      }
      
      // 5. Handlebars syntax: class="{{className}}" or class="uls-button {{#if active}}active{{/if}}"
      const handlebarsClassRegex = /\bclass\s*=\s*["']([^"']+)["']/g
      while ((match = handlebarsClassRegex.exec(content)) !== null) {
        const classAttr = match[1]
        // Extract static class names (ignore Handlebars expressions like {{className}})
        // Match patterns like: "uls-button", "uls-button {{#if}}", "{{className}} uls-button"
        const staticClasses = classAttr
          .replace(/\{\{[^}]+\}\}/g, '') // Remove Handlebars expressions
          .split(/\s+/)
          .filter(Boolean)
        staticClasses.forEach(cls => classNames.add(cls))
      }
      
      // 6. NO FALLBACK - Only extract from actual class attributes and function calls
      // This prevents matching generic words like "pointer", "text", "block" from CSS content
      // Only classes explicitly used in className/class attributes are extracted
      
      return Array.from(classNames)
    },
    variables: true, // Keep CSS variables
    keyframes: true,  // Keep keyframes
  }
}

